    "cookTime": "PT5M",
    "totalTime": "PT15M",
    "image": "https://caribbeanpot.com/wp-content/uploads/2020/06/pineapple-chow-11.jpg",
    "imageCredit": "CaribbeanPot.com (caribbeanpot.com)"
